      const overlaps = rs => { let n = 0; rs.forEach((a, i) => rs.forEach((c, j) => { if (i < j && a.left < c.right - 1 && c.left < a.right - 1 && a.top < c.bottom - 1 && c.top < a.bottom - 1) n++; })); return n; };
