        ok('items: a Wand of the War Mage raises the spell attack', sktComputeCharacter(wz, R14).sheet.spellAtkBonus === sktSigned(parseInt(W0.sheet.spellAtkBonus, 10) + 2), sktComputeCharacter(wz, R14).sheet.spellAtkBonus);

