              CS.tab = ids[0]; csRender();
              await swipe(root.querySelector('.cs-pane'), 300, 60);
              ok('sheet: swiping left goes to the next tab', CS.tab === ids[1], CS.tab);
              await swipe(root.querySelector('.cs-pane'), 60, 300);
